import {jest} from '@jest/globals';
import {setLogger} from '../../shared/logger.js';
import {ToolRegistry} from './registry.js';

describe('nested validation paths [specs/hal-engine-tool-input-validation/spec.md#4]', () => {
  it('identifies the nested path of an invalid property', async () => {
    const warn = jest.fn();
    setLogger({debug: jest.fn(), info: jest.fn(), warn, error: jest.fn()});
    try {
      const registry = new ToolRegistry();
      registry.register({name: 'nested', description: 'Nested', inputSchema: {
        type: 'object', properties: {address: {type: 'object', properties: {city: {type: 'string'}}}},
      }}, async () => 'ok');
      const response = await registry.execute('nested', {address: {city: 7}});
      expect(response.result).toMatch(/address.*city.*string/);
      expect(JSON.stringify(warn.mock.calls)).toContain('/address/city');
    } finally {
      setLogger();
    }
  });
});
EOF
